    sieve = [True] * (sqrt_r + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(math.isqrt(sqrt_r)) + 1):
        if sieve[i]:
            sieve[i*i : sqrt_r + 1 : i*i] = [False] * len(range(i*i, sqrt_r + 1, i*i))

    primes = [i for i in range(2, sqrt_r + 1) if sieve[i]]

