def solution(input_str):
    """
    Given a sequence as input string, determine:
    0 = already a geometric progression
    1 = can become GP by removing one element
    2 = neither
    """

    def is_geometric(seq):
        """Check if sequence is geometric"""
        n = len(seq)
        if n <= 2:
            return True

        # All zeros case
        if all(x == 0 for x in seq):
            return True

        # First element determines if ratio exists
        if seq[0] == 0:
            # If first is 0, second must be 0 for valid GP
            if seq[1] != 0:
                return False
            # All others must be 0
            for i in range(2, n):
                if seq[i] != 0:
                    return False
            return True

        # Calculate expected ratio from first two elements
        ratio_num = seq[1]
        ratio_den = seq[0]

        # Verify all consecutive ratios match
        for i in range(2, n):
            a, b = seq[i-1], seq[i]

            if a == 0:
                if b != 0:
                    return False
            else:
                # Cross multiply: b/a should equal ratio_num/ratio_den
                if a * ratio_num != b * ratio_den:
                    return False

        return True

    def remove_one_and_check(arr, idx):
        """Check if removing arr[idx] yields a geometric progression"""
        new_arr = arr[:idx] + arr[idx+1:]
        return is_geometric(new_arr)

    # Parse input
    import sys
    try:
        lines = input_str.strip().split('\n')
        if not lines:
            return "2\n"

        n = int(lines[0])
        parts = lines[1].split() if len(lines) > 1 else []
        arr = [int(x) for x in parts]

        # Ensure we have exactly n elements
        while len(arr) < n:
            arr.append(0)
        arr = arr[:n]
    except:
        return "2\n"

    # Answer for single element
    if len(arr) == 1:
        return "0\n"

    # Check if currently geometric
    if is_geometric(arr):
        return "0\n"

    # Try removing each element
    for i in range(len(arr)):
        if remove_one_and_check(arr, i):
            return "1\n"

    return "2\n"
