import sys

def parse_tree(data, start_idx):
    """Parse tree from input string"""
    lines = data.split('\n')
    idx = start_idx

    n = int(lines[idx])
    idx += 1

    tree = {}
    for i in range(n):
        parts = lines[idx].split()
        idx += 1
        if parts[0] == '-1':
            tree[i] = {'type': 0, 'l': int(parts[1]), 'r': int(parts[2])}
        else:
            tree[i] = {'type': 1, 'val': int(parts[0])]

    return tree, idx

def count_leaves(node, tree):
    """Count number of leaf nodes in a subtree"""
    if tree[node]['type'] == 1:
        return 1
    return count_leaves(tree[node]['l'], tree) + count_leaves(tree[node]['r'], tree)

def solve_game(tree, root):
    """Solve the game using minimax"""
    @lru_cache(None)
    def dp(node, turn):
        """
        Turn 0: Pieguy wants to maximize
        Turn 1: Piegirl wants to minimize
        """
        if tree[node]['type'] == 1:
            return tree[node]['val']

        # Recursively calculate
        left_val = dp(tree[node]['l'], turn)
        right_val = dp(tree[node]['r'], turn)

        # Game theory on merges
        if turn == 0:  # Pieguy maximizes
            return max(left_val, right_val)
        else:  # Piegirl minimizes
            return min(left_val, right_val)

    return dp(root, 0)

def solution(input_data: str):
    tree, _ = parse_tree(input_data)
    return str(solve_game(tree, 0))
