def solution(input_data):
    """
    Solves the maximum operations problem where we can divide pairs of numbers
    by their common factors, with constraints on which pairs can be used.

    The key insight is that this can be modeled as a max flow problem for each
    prime factor independently, where odd-indexed positions can pair with even-
    indexed positions through the good pairs.
    """
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Parse good pairs (convert to 0-indexed)
    pairs = []
    for i in range(m):
        u, v = map(int, lines[2 + i].split())
        pairs.append((u - 1, v - 1))

    # Helper to count prime factorization
    def get_prime_factors(x):
        if x <= 1:
            return {}
        factors = {}
        d = 2
        temp = x
        while d * d <= temp:
            if temp % d == 0:
                count = 0
                while temp % d == 0:
                    count += 1
                    temp //= d
                factors[d] = count
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    # Collect all prime factors used
    all_primes = set()
    for val in a:
        for p in get_prime_factors(val):
            all_primes.add(p)

    class Dinic:
        """Dinic's algorithm for maximum bipartite matching"""
        def __init__(self):
            self.graph = [[]]
            self.level = []
            self.ptr = []

        def reset(self, n):
            self.graph = [[] for _ in range(n)]
            self.level = [-1] * n
            self.ptr = [0] * n

        def add_edge(self, u, v, capacity):
            self.graph[u].append([v, len(self.graph[v]), capacity])
            self.graph[v].append([u, len(self.graph[u]) - 1, 0])

        def bfs(self, s, t):
            self.level = [-1] * len(self.graph)
            self.level[s] = 0
            queue = [s]
            while queue:
                u = queue.pop(0)
                for v, rev, cap in self.graph[u]:
                    if cap > 0 and self.level[v] == -1:
                        self.level[v] = self.level[u] + 1
                        queue.append(v)

        def dfs(self, u, t, flow):
            if flow == 0 or u == t:
                return flow
            for i in range(self.ptr[u], len(self.graph[u])):
                self.ptr[u] = i
                v, rev, cap = self.graph[u][i]
                if self.level[v] != self.level[u] + 1 or cap == 0:
                    continue
                pushed = self.dfs(v, t, min(flow, cap))
                if pushed > 0:
                    self.graph[u][i][2] -= pushed
                    self.graph[v][rev][2] += pushed
                    return pushed
            return 0

        def max_flow(self, s, t):
            result = 0
            while True:
                self.reset(len(self.graph))
                self.bfs(s, t)
                if self.level[t] == -1:
                    break
                self.ptr = [0] * len(self.graph)
                while True:
                    pushed = self.dfs(s, t, float('inf'))
                    if pushed == 0:
                        break
                    result += pushed
            return result

    total = 0

    for p in all_primes:
        # Count occurrences of prime p at odd and even indices (1-indexed positions)
        odd_cnt = [0] * n
        even_cnt = [0] * n

        for i, val in enumerate(a):
            pos = i + 1  # 1-indexed position
            factors = get_prime_factors(val)
            if p in factors:
                count = factors[p]
                if pos % 2 == 1:
                    odd_cnt[i] = count
                else:
                    even_cnt[i] = count

        node_odd = n + 1  # source node
        node_even = 2 * n  # sink node

        dinic = Dinic()
        dinic.reset(node_odd + 100)

        # Source connects to odd positions
        for i in range(n):
            cap = odd_cnt[i]
            if cap > 0:
                dinic.add_edge(node_odd, i + node_odd, cap)

        # Even positions connect to sink
        for i in range(n):
            cap = even_cnt[i]
            if cap > 0:
                dinic.add_edge(i + node_even + 1, node_even + 100, cap)

        # Good pairs form edges between odd and even positions
        for u, v in pairs:
            # Check if indices have different parity (1-indexed)
            if (u + 1) % 2 != (v + 1) % 2:
                dinic.add_edge(u + node_odd, v + node_even + 1, float('inf'))
            if (u + 1) % 2 != (v + 1) % 2:
                dinic.add_edge(v + node_odd, u + node_even + 1, float('inf'))

        total += dinic.max_flow(node_odd, node_even + 100)

    return str(total) + '\n'
