    c = list(map(int, lines[1].split()))

    special = {}
    for i in range(2, 2 + q):
        p, w = map(int, lines[i].split())
        special[p] = w

    if n == x:
        return '0\n'

    # dp[i] = minimum energy to have x pollywogs at consecutive positions starting at i
    # Initial: dp[1] = 0
    # Target: dp[n-x+1]

    INF = float('inf')
    dp = [INF] * (n - x + 2)
    dp[1] = 0

