            continue
        # Try all valid jump distances
        for d in range(1, k + 1):
            if i + d <= n - x + 1:
                cost = c[d - 1] + special.get(i + d, 0)
                if dp[i] + cost < dp[i + d]:
                    dp[i + d] = dp[i] + cost

    return str(int(dp[n - x + 1])) + '\n' if dp[n - x + 1] != INF else '0\n'
