def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    idx = 1
    results = []

    for _ in range(q):
        if idx >= len(lines):
            break
        a, b = map(int, lines[idx].split())
        idx += 1
        if idx >= len(lines):
            break
        s = lines[idx]
        idx += 1

        # Find all consecutive '.' segments
        gaps = []
        i = 0
        n = len(s)
        while i < n:
            j = i
            while j < n and s[j] == '.':
                j += 1
            if j > i:
                gaps.append(j - i)
            i = j

        # Alice wins if she can make the first move (any gap >= a)
        if any(gap >= a for gap in gaps):
            results.append("YES")
        else:
            results.append("NO")

    return '\n'.join(results)
