MOD = 10**9 + 7

def solution(input_str):
    try:
        n, k, m = map(int, input_str.strip().split())
    except:
        return "0"

    if k == 1:
        return str(n % MOD)
    if k > n:
        return "0"

    memo = {}

    def dfs(cur, visited_tuple, depth):
        if depth == k:
            return 1

        state = (cur, depth, visited_tuple)
        if state in memo:
            return memo[state]

        res = 0
        upper = min(n, cur + m)

        for nxt in range(1, upper + 1):
            if nxt not in visited_tuple:
                new_visited = visited_tuple + (nxt,)
                res = (res + dfs(nxt, new_visited, depth + 1)) % MOD

        memo[state] = res
        return res

    total = 0
    for start in range(1, min(n, k * m + k) + 1):
        total = (total + dfs(start, (start,), 1)) % MOD

    return str(total)


